1	// Package reports computes the dashboard's reports.
2	package reports
3	
4	import (
5		"errors"
6		"fmt"
7		"sort"
8		"time"
9	
10		"example.com/tally/internal/money"
11		"example.com/tally/internal/store"
12	)
13	
14	// DayRevenue is what an organization took on one day in one currency.
15	type DayRevenue struct {
16		Date     string         `json:"date"` // YYYY-MM-DD
17		Currency money.Currency `json:"currency"`
18		Amount   int64          `json:"amount"`
19		Payments int            `json:"payments"`
20	}
21	
22	// Errors.
23	var (
24		ErrInvalidDate  = errors.New("invalid date")
25		ErrInvalidRange = errors.New("invalid date range")
26	)
27	
28	// MaxDays is the longest range a report covers.
29	const MaxDays = 366
30	
31	// Revenue adds up the organization's succeeded payments per day and currency, from the day from to the day to (YYYY-MM-DD,
32	// both included). Days are UTC days. The result is in date order, currencies in alphabetical order within a day; days
33	// without payments are left out.
34	func Revenue(st *store.Store, orgID, from, to string) ([]DayRevenue, error) {
35		start, err := time.Parse(time.DateOnly, from)
36		if err != nil {
37			return nil, fmt.Errorf("%w: from %q", ErrInvalidDate, from)
38		}
39		last, err := time.Parse(time.DateOnly, to)
40		if err != nil {
41			return nil, fmt.Errorf("%w: to %q", ErrInvalidDate, to)
42		}
43		if last.Before(start) {
44			return nil, fmt.Errorf("%w: to is before from", ErrInvalidRange)
45		}
46		if last.Sub(start) >= MaxDays*24*time.Hour {
47			return nil, fmt.Errorf("%w: at most %d days", ErrInvalidRange, MaxDays)
48		}
49		end := last.AddDate(0, 0, 1)
50		type key struct {
51			day string
52			cur money.Currency
53		}
54		sums := map[key]*DayRevenue{}
55		for _, p := range st.Payments(orgID, "") {
56			if p.Status != store.PaymentSucceeded || p.CreatedAt.Before(start) || !p.CreatedAt.Before(end) {
57				continue
58			}
59			k := key{p.CreatedAt.UTC().Format(time.DateOnly), p.Currency}
60			d, ok := sums[k]
61			if !ok {
62				d = &DayRevenue{Date: k.day, Currency: k.cur}
63				sums[k] = d
64			}
65			d.Amount += p.Amount
66			d.Payments++
67		}
68		out := make([]DayRevenue, 0, len(sums))
