29	const MaxDays = 366
30	
31	// Revenue adds up the organization's succeeded payments per day and currency, from the day from to the day to (YYYY-MM-DD,
32	// both included). Days are UTC days. The result is in date order, currencies in alphabetical order within a day; days
33	// without payments are left out.
34	func Revenue(st *store.Store, orgID, from, to string) ([]DayRevenue, error) {
35		start, err := time.Parse(time.DateOnly, from)
36		if err != nil {
